contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;

        assert(!reverted || (balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore && address(this).balance == thisBalanceBefore));
    }

    receive() external payable {}
}

