    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 unlockTimeBefore;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeBefore = __r0; balanceBefore = __r1; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 unlockTimeAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeAfter = __r0; balanceAfter = __r1; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        assertTrue(!reverted || (balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore && address(this).balance == thisBalanceBefore));
    }

    function testFuzz_run(uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        _run(lockTime, putAmount, collectAmount);
